CREATE TABLE Sale (
    saleID INT NOT NULL
        CHECK (saleID > 0),
    modelID INT NOT NULL,
    saleDate DATE,
    employeeID VARCHAR(10) NOT NULL,
    price FLOAT
        CHECK (price >= 0.0),
    PRIMARY KEY (saleID),
    FOREIGN KEY (modelID)
        REFERENCES Model (modelID),
    FOREIGN KEY (employeeID)
        REFERENCES Employee (employeeID)
);

